const body = $input.first().json.body || $input.first().json || {};
const nomFichier = (body.nom_fichier || 'tableur_jarvis.xlsx').trim();
const colonnes = Array.isArray(body.colonnes) ? body.colonnes : [];
const lignes = Array.isArray(body.lignes) ? body.lignes : [];

const items = [];
if (lignes.length > 0) {
  for (const row of lignes) {
    const rowObj = {};
    colonnes.forEach((col, idx) => {
      rowObj[col] = (Array.isArray(row) && row[idx] !== undefined) ? row[idx] : '';
    });
    items.push({ json: rowObj });
  }
} else {
  const emptyObj = {};
  colonnes.forEach(c => emptyObj[c] = '');
  items.push({ json: emptyObj });
}

return items;

const body = $input.first().json.body || $input.first().json || {};
const titre = (body.titre || (body.slides_data && body.slides_data.title) || 'Présentation Jarvis').trim();
const subtitle = (body.subtitle || (body.slides_data && body.slides_data.subtitle) || '').trim();
const theme = (body.theme || (body.slides_data && body.slides_data.theme) || 'stark').trim().toLowerCase();
const slides = Array.isArray(body.slides) ? body.slides : ((body.slides_data && Array.isArray(body.slides_data.slides)) ? body.slides_data.slides : []);
const batchRequests = Array.isArray(body.batch_requests) ? body.batch_requests : [];
const cleanSlug = (body.clean_slug || titre.replace(/[^a-zA-Z0-9_-]/g, '_').toLowerCase()) || 'presentation';
const slidesData = body.slides_data || { title: titre, subtitle: subtitle, theme: theme, slides: slides };

return [{
  json: {
    titre: titre,
    subtitle: subtitle,
    theme: theme,
    slides: slides,
    slides_data: slidesData,
    slides_count: slides.length,
    batch_requests: batchRequests,
    clean_slug: cleanSlug,
    filename: cleanSlug + '.pptx',
    downloads_path: '/home/opc/jarvis-core/downloads/' + cleanSlug + '.pptx',
    download_url: '/downloads/' + cleanSlug + '.pptx'
  }
}];

const inputData = $input.first().json;
const prepNode = ($node && $node['Préparer Présentation']) ? $node['Préparer Présentation'].json : {};
const presentationId = inputData.presentationId || (inputData.data && inputData.data.presentationId) || inputData.id || prepNode.presentationId;
const slidesData = inputData.slides_data || prepNode.slides_data || (prepNode.slides ? prepNode : inputData);

if (!presentationId) {
  throw new Error("presentationId introuvable pour générer le batchUpdate Google Slides");
}

const themeColors = {
  stark: {
    bg: { red: 0.04, green: 0.07, blue: 0.11 },
    accent: { red: 0.22, green: 0.74, blue: 0.97 },
    cardBg: { red: 0.07, green: 0.11, blue: 0.18 },
    text: { red: 0.95, green: 0.97, blue: 1.0 },
    subtext: { red: 0.58, green: 0.65, blue: 0.75 }
  },
  gold: {
    bg: { red: 0.08, green: 0.07, blue: 0.05 },
    accent: { red: 0.96, green: 0.72, blue: 0.20 },
    cardBg: { red: 0.14, green: 0.12, blue: 0.09 },
    text: { red: 1.0, green: 0.98, blue: 0.92 },
    subtext: { red: 0.78, green: 0.72, blue: 0.60 }
  },
  bitcoin: {
    bg: { red: 0.08, green: 0.07, blue: 0.05 },
    accent: { red: 0.96, green: 0.72, blue: 0.20 },
    cardBg: { red: 0.14, green: 0.12, blue: 0.09 },
    text: { red: 1.0, green: 0.98, blue: 0.92 },
    subtext: { red: 0.78, green: 0.72, blue: 0.60 }
  },
  corporate: {
    bg: { red: 0.98, green: 0.99, blue: 1.0 },
    accent: { red: 0.08, green: 0.38, blue: 0.75 },
    cardBg: { red: 0.92, green: 0.95, blue: 0.98 },
    text: { red: 0.08, green: 0.12, blue: 0.18 },
    subtext: { red: 0.35, green: 0.42, blue: 0.52 }
  },
  dark: {
    bg: { red: 0.06, green: 0.07, blue: 0.09 },
    accent: { red: 0.55, green: 0.36, blue: 0.96 },
    cardBg: { red: 0.11, green: 0.13, blue: 0.17 },
    text: { red: 0.96, green: 0.97, blue: 0.99 },
    subtext: { red: 0.60, green: 0.64, blue: 0.72 }
  },
  cyber: {
    bg: { red: 0.03, green: 0.03, blue: 0.06 },
    accent: { red: 0.66, green: 0.33, blue: 0.97 },
    cardBg: { red: 0.08, green: 0.06, blue: 0.16 },
    text: { red: 1.0, green: 1.0, blue: 1.0 },
    subtext: { red: 0.65, green: 0.60, blue: 0.75 }
  }
};

const selectedTheme = themeColors[slidesData.theme] || themeColors.stark;
const requests = [];
const SLIDE_WIDTH = 720;
const SLIDE_HEIGHT = 405;

let firstSlideId = null;
if (inputData.slides && inputData.slides.length > 0) {
  firstSlideId = inputData.slides[0].objectId;
}

const slidesList = slidesData.slides || [];

slidesList.forEach((slide, index) => {
  const slideId = "slide_jarvis_" + index + "_" + Date.now();
  requests.push({
    createSlide: {
      objectId: slideId,
      insertionIndex: index,
      slideLayoutProperties: { masterLayoutReferenceId: "BLANK" }
    }
  });

  // Fond de slide
  requests.push({
    updatePageProperties: {
      objectId: slideId,
      pageProperties: {
        pageBackgroundFill: {
          solidFill: { color: { rgbColor: selectedTheme.bg } }
        }
      },
      fields: "pageBackgroundFill"
    }
  });

  const layout = slide.layout || "cards_grid";

  if (layout === "hero_title") {
    const titleBoxId = slideId + "_title";
    requests.push({
      createShape: {
        objectId: titleBoxId,
        shapeType: "TEXT_BOX",
        elementProperties: {
          pageObjectId: slideId,
          size: { width: { magnitude: 620, unit: "PT" }, height: { magnitude: 120, unit: "PT" } },
          transform: { scaleX: 1, scaleY: 1, translateX: 50, translateY: 100, unit: "PT" }
        }
      }
    });
    requests.push({
      insertText: {
        objectId: titleBoxId,
        text: (slide.title || slide.titre_slide || "").toUpperCase(),
        insertionIndex: 0
      }
    });
    requests.push({
      updateTextStyle: {
        objectId: titleBoxId,
        style: {
          bold: true,
          fontFamily: "Trebuchet MS",
          fontSize: { magnitude: 34, unit: "PT" },
          foregroundColor: { opaqueColor: { rgbColor: selectedTheme.accent } }
        },
        fields: "bold,fontFamily,fontSize,foregroundColor"
      }
    });

    const subText = slide.subtitle || (slide.points && slide.points[0]) || "";
    if (subText) {
      const subBoxId = slideId + "_sub";
      requests.push({
        createShape: {
          objectId: subBoxId,
          shapeType: "TEXT_BOX",
          elementProperties: {
            pageObjectId: slideId,
            size: { width: { magnitude: 620, unit: "PT" }, height: { magnitude: 90, unit: "PT" } },
            transform: { scaleX: 1, scaleY: 1, translateX: 50, translateY: 230, unit: "PT" }
          }
        }
      });
      requests.push({
        insertText: {
          objectId: subBoxId,
          text: subText,
          insertionIndex: 0
        }
      });
      requests.push({
        updateTextStyle: {
          objectId: subBoxId,
          style: {
            fontFamily: "Arial",
            fontSize: { magnitude: 18, unit: "PT" },
            foregroundColor: { opaqueColor: { rgbColor: selectedTheme.subtext } }
          },
          fields: "fontFamily,fontSize,foregroundColor"
        }
      });
    }

  } else if (layout === "key_metrics") {
    // Titre haut
    const titleId = slideId + "_title";
    requests.push({
      createShape: {
        objectId: titleId,
        shapeType: "TEXT_BOX",
        elementProperties: {
          pageObjectId: slideId,
          size: { width: { magnitude: 640, unit: "PT" }, height: { magnitude: 50, unit: "PT" } },
          transform: { scaleX: 1, scaleY: 1, translateX: 40, translateY: 25, unit: "PT" }
        }
      }
    });
    requests.push({
      insertText: { objectId: titleId, text: slide.title || slide.titre_slide || "", insertionIndex: 0 }
    });
    requests.push({
      updateTextStyle: {
        objectId: titleId,
        style: {
          bold: true,
          fontSize: { magnitude: 22, unit: "PT" },
          foregroundColor: { opaqueColor: { rgbColor: selectedTheme.text } }
        },
        fields: "bold,fontSize,foregroundColor"
      }
    });

    const metrics = slide.metrics || (slide.key_metric ? [slide.key_metric] : []);
    const count = Math.max(1, metrics.length);
    const availableWidth = 640;
    const cardGap = 16;
    const cardW = (availableWidth - (cardGap * (count - 1))) / count;
    const cardH = 240;
    const startY = 95;

    metrics.forEach((m, mIdx) => {
      const cardX = 40 + mIdx * (cardW + cardGap);
      const cardShapeId = slideId + "_mcard_" + mIdx;
      requests.push({
        createShape: {
          objectId: cardShapeId,
          shapeType: "ROUND_RECTANGLE",
          elementProperties: {
            pageObjectId: slideId,
            size: { width: { magnitude: cardW, unit: "PT" }, height: { magnitude: cardH, unit: "PT" } },
            transform: { scaleX: 1, scaleY: 1, translateX: cardX, translateY: startY, unit: "PT" }
          }
        }
      });
      requests.push({
        updateShapeProperties: {
          objectId: cardShapeId,
          shapeProperties: {
            shapeBackgroundFill: { solidFill: { color: { rgbColor: selectedTheme.cardBg } } },
            outline: { outlineFill: { solidFill: { color: { rgbColor: selectedTheme.accent } } }, weight: { magnitude: 1.5, unit: "PT" } }
          },
          fields: "shapeBackgroundFill,outline"
        }
      });

      const mTextId = slideId + "_mtext_" + mIdx;
      requests.push({
        createShape: {
          objectId: mTextId,
          shapeType: "TEXT_BOX",
          elementProperties: {
            pageObjectId: slideId,
            size: { width: { magnitude: cardW - 20, unit: "PT" }, height: { magnitude: cardH - 20, unit: "PT" } },
            transform: { scaleX: 1, scaleY: 1, translateX: cardX + 10, translateY: startY + 15, unit: "PT" }
          }
        }
      });
      const metricContent = (m.value || "") + "

" + (m.label || "") + (m.subtext || m.desc ? ("
" + (m.subtext || m.desc)) : "");
      requests.push({
        insertText: { objectId: mTextId, text: metricContent, insertionIndex: 0 }
      });
      requests.push({
        updateTextStyle: {
          objectId: mTextId,
          style: {
            bold: true,
            fontSize: { magnitude: 36, unit: "PT" },
            foregroundColor: { opaqueColor: { rgbColor: selectedTheme.accent } }
          },
          fields: "bold,fontSize,foregroundColor"
        }
      });
    });

  } else if (layout === "split_compare") {
    const titleId = slideId + "_title";
    requests.push({
      createShape: {
        objectId: titleId,
        shapeType: "TEXT_BOX",
        elementProperties: {
          pageObjectId: slideId,
          size: { width: { magnitude: 640, unit: "PT" }, height: { magnitude: 50, unit: "PT" } },
          transform: { scaleX: 1, scaleY: 1, translateX: 40, translateY: 25, unit: "PT" }
        }
      }
    });
    requests.push({
      insertText: { objectId: titleId, text: slide.title || slide.titre_slide || "Comparaison", insertionIndex: 0 }
    });
    requests.push({
      updateTextStyle: {
        objectId: titleId,
        style: { bold: true, fontSize: { magnitude: 22, unit: "PT" }, foregroundColor: { opaqueColor: { rgbColor: selectedTheme.text } } },
        fields: "bold,fontSize,foregroundColor"
      }
    });

    const colW = 310;
    const colH = 280;
    const colY = 85;

    // Colonne gauche
    const leftCardId = slideId + "_col_left";
    requests.push({
      createShape: {
        objectId: leftCardId,
        shapeType: "ROUND_RECTANGLE",
        elementProperties: {
          pageObjectId: slideId,
          size: { width: { magnitude: colW, unit: "PT" }, height: { magnitude: colH, unit: "PT" } },
          transform: { scaleX: 1, scaleY: 1, translateX: 40, translateY: colY, unit: "PT" }
        }
      }
    });
    requests.push({
      updateShapeProperties: {
        objectId: leftCardId,
        shapeProperties: {
          shapeBackgroundFill: { solidFill: { color: { rgbColor: selectedTheme.cardBg } } },
          outline: { outlineFill: { solidFill: { color: { rgbColor: selectedTheme.subtext } } }, weight: { magnitude: 1, unit: "PT" } }
        },
        fields: "shapeBackgroundFill,outline"
      }
    });

    const leftTextId = slideId + "_txt_left";
    const leftCol = slide.left_column || {};
    const leftTitle = (leftCol.title || "Avant").toUpperCase();
    const leftPoints = (leftCol.points || []).map(p => "• " + p).join("

");
    requests.push({
      createShape: {
        objectId: leftTextId,
        shapeType: "TEXT_BOX",
        elementProperties: {
          pageObjectId: slideId,
          size: { width: { magnitude: colW - 30, unit: "PT" }, height: { magnitude: colH - 30, unit: "PT" } },
          transform: { scaleX: 1, scaleY: 1, translateX: 55, translateY: colY + 15, unit: "PT" }
        }
      }
    });
    requests.push({
      insertText: { objectId: leftTextId, text: leftTitle + "

" + leftPoints, insertionIndex: 0 }
    });
    requests.push({
      updateTextStyle: {
        objectId: leftTextId,
        style: { fontSize: { magnitude: 13, unit: "PT" }, foregroundColor: { opaqueColor: { rgbColor: selectedTheme.text } } },
        fields: "fontSize,foregroundColor"
      }
    });

    // Colonne droite
    const rightCardId = slideId + "_col_right";
    requests.push({
      createShape: {
        objectId: rightCardId,
        shapeType: "ROUND_RECTANGLE",
        elementProperties: {
          pageObjectId: slideId,
          size: { width: { magnitude: colW, unit: "PT" }, height: { magnitude: colH, unit: "PT" } },
          transform: { scaleX: 1, scaleY: 1, translateX: 370, translateY: colY, unit: "PT" }
        }
      }
    });
    requests.push({
      updateShapeProperties: {
        objectId: rightCardId,
        shapeProperties: {
          shapeBackgroundFill: { solidFill: { color: { rgbColor: selectedTheme.cardBg } } },
          outline: { outlineFill: { solidFill: { color: { rgbColor: selectedTheme.accent } } }, weight: { magnitude: 1.5, unit: "PT" } }
        },
        fields: "shapeBackgroundFill,outline"
      }
    });

    const rightTextId = slideId + "_txt_right";
    const rightCol = slide.right_column || {};
    const rightTitle = (rightCol.title || "Après / Cible").toUpperCase();
    const rightPoints = (rightCol.points || []).map(p => "✔ " + p).join("

");
    requests.push({
      createShape: {
        objectId: rightTextId,
        shapeType: "TEXT_BOX",
        elementProperties: {
          pageObjectId: slideId,
          size: { width: { magnitude: colW - 30, unit: "PT" }, height: { magnitude: colH - 30, unit: "PT" } },
          transform: { scaleX: 1, scaleY: 1, translateX: 385, translateY: colY + 15, unit: "PT" }
        }
      }
    });
    requests.push({
      insertText: { objectId: rightTextId, text: rightTitle + "

" + rightPoints, insertionIndex: 0 }
    });
    requests.push({
      updateTextStyle: {
        objectId: rightTextId,
        style: { fontSize: { magnitude: 13, unit: "PT" }, foregroundColor: { opaqueColor: { rgbColor: selectedTheme.text } } },
        fields: "fontSize,foregroundColor"
      }
    });

  } else if (layout === "timeline_steps") {
    const titleId = slideId + "_title";
    requests.push({
      createShape: {
        objectId: titleId,
        shapeType: "TEXT_BOX",
        elementProperties: {
          pageObjectId: slideId,
          size: { width: { magnitude: 640, unit: "PT" }, height: { magnitude: 45, unit: "PT" } },
          transform: { scaleX: 1, scaleY: 1, translateX: 40, translateY: 25, unit: "PT" }
        }
      }
    });
    requests.push({
      insertText: { objectId: titleId, text: slide.title || slide.titre_slide || "Feuille de Route", insertionIndex: 0 }
    });
    requests.push({
      updateTextStyle: {
        objectId: titleId,
        style: { bold: true, fontSize: { magnitude: 20, unit: "PT" }, foregroundColor: { opaqueColor: { rgbColor: selectedTheme.text } } },
        fields: "bold,fontSize,foregroundColor"
      }
    });

    const steps = slide.steps || [];
    const count = Math.min(4, Math.max(1, steps.length));
    const availableWidth = 640;
    const cardGap = 14;
    const cardW = (availableWidth - (cardGap * (count - 1))) / count;
    const cardH = 265;
    const startY = 85;

    steps.slice(0, count).forEach((st, sIdx) => {
      const cardX = 40 + sIdx * (cardW + cardGap);
      const cardShapeId = slideId + "_step_" + sIdx;
      requests.push({
        createShape: {
          objectId: cardShapeId,
          shapeType: "ROUND_RECTANGLE",
          elementProperties: {
            pageObjectId: slideId,
            size: { width: { magnitude: cardW, unit: "PT" }, height: { magnitude: cardH, unit: "PT" } },
            transform: { scaleX: 1, scaleY: 1, translateX: cardX, translateY: startY, unit: "PT" }
          }
        }
      });
      requests.push({
        updateShapeProperties: {
          objectId: cardShapeId,
          shapeProperties: {
            shapeBackgroundFill: { solidFill: { color: { rgbColor: selectedTheme.cardBg } } },
            outline: { outlineFill: { solidFill: { color: { rgbColor: selectedTheme.accent } } }, weight: { magnitude: 1.2, unit: "PT" } }
          },
          fields: "shapeBackgroundFill,outline"
        }
      });

      const stepTextId = slideId + "_steptxt_" + sIdx;
      requests.push({
        createShape: {
          objectId: stepTextId,
          shapeType: "TEXT_BOX",
          elementProperties: {
            pageObjectId: slideId,
            size: { width: { magnitude: cardW - 20, unit: "PT" }, height: { magnitude: cardH - 20, unit: "PT" } },
            transform: { scaleX: 1, scaleY: 1, translateX: cardX + 10, translateY: startY + 12, unit: "PT" }
          }
        }
      });
      const stepContent = "[" + (st.phase || ("0" + (sIdx + 1))) + "]

" + (st.title || "").toUpperCase() + "

" + (st.desc || "");
      requests.push({
        insertText: { objectId: stepTextId, text: stepContent, insertionIndex: 0 }
      });
      requests.push({
        updateTextStyle: {
          objectId: stepTextId,
          style: { fontSize: { magnitude: 12, unit: "PT" }, foregroundColor: { opaqueColor: { rgbColor: selectedTheme.text } } },
          fields: "fontSize,foregroundColor"
        }
      });
    });

  } else {
    // Par défaut : cards_grid dynamique (2, 3 ou 4 cartes)
    const titleId = slideId + "_title";
    requests.push({
      createShape: {
        objectId: titleId,
        shapeType: "TEXT_BOX",
        elementProperties: {
          pageObjectId: slideId,
          size: { width: { magnitude: 640, unit: "PT" }, height: { magnitude: 45, unit: "PT" } },
          transform: { scaleX: 1, scaleY: 1, translateX: 40, translateY: 25, unit: "PT" }
        }
      }
    });
    requests.push({
      insertText: { objectId: titleId, text: slide.title || slide.titre_slide || "", insertionIndex: 0 }
    });
    requests.push({
      updateTextStyle: {
        objectId: titleId,
        style: { bold: true, fontSize: { magnitude: 20, unit: "PT" }, foregroundColor: { opaqueColor: { rgbColor: selectedTheme.text } } },
        fields: "bold,fontSize,foregroundColor"
      }
    });

    let cards = slide.cards || [];
    if (!cards.length && slide.points && Array.isArray(slide.points)) {
      cards = slide.points.map((p, i) => ({ title: "Point " + (i + 1), body: p, badge: "INFO" }));
    }
    const count = Math.min(4, Math.max(1, cards.length));
    const availableWidth = 640;
    const cardGap = 14;
    const cardW = (availableWidth - (cardGap * (count - 1))) / count;
    const cardH = 265;
    const startY = 85;

    cards.slice(0, count).forEach((card, cIdx) => {
      const cardX = 40 + cIdx * (cardW + cardGap);
      const cardShapeId = slideId + "_card_" + cIdx;
      requests.push({
        createShape: {
          objectId: cardShapeId,
          shapeType: "ROUND_RECTANGLE",
          elementProperties: {
            pageObjectId: slideId,
            size: { width: { magnitude: cardW, unit: "PT" }, height: { magnitude: cardH, unit: "PT" } },
            transform: { scaleX: 1, scaleY: 1, translateX: cardX, translateY: startY, unit: "PT" }
          }
        }
      });
      requests.push({
        updateShapeProperties: {
          objectId: cardShapeId,
          shapeProperties: {
            shapeBackgroundFill: { solidFill: { color: { rgbColor: selectedTheme.cardBg } } },
            outline: { outlineFill: { solidFill: { color: { rgbColor: selectedTheme.accent } } }, weight: { magnitude: 1, unit: "PT" } }
          },
          fields: "shapeBackgroundFill,outline"
        }
      });

      const cardTextId = slideId + "_cardtxt_" + cIdx;
      requests.push({
        createShape: {
          objectId: cardTextId,
          shapeType: "TEXT_BOX",
          elementProperties: {
            pageObjectId: slideId,
            size: { width: { magnitude: cardW - 20, unit: "PT" }, height: { magnitude: cardH - 20, unit: "PT" } },
            transform: { scaleX: 1, scaleY: 1, translateX: cardX + 10, translateY: startY + 12, unit: "PT" }
          }
        }
      });
      const cardContent = (card.badge ? "[" + card.badge + "]

" : "") + (card.title || "").toUpperCase() + "

" + (card.body || "");
      requests.push({
        insertText: { objectId: cardTextId, text: cardContent, insertionIndex: 0 }
      });
      requests.push({
        updateTextStyle: {
          objectId: cardTextId,
          style: { fontSize: { magnitude: 12, unit: "PT" }, foregroundColor: { opaqueColor: { rgbColor: selectedTheme.text } } },
          fields: "fontSize,foregroundColor"
        }
      });
    });
  }
});

// Supprimer la première diapositive vierge initiale si elle existe
if (firstSlideId && slidesList.length > 0) {
  requests.push({
    deleteObject: {
      objectId: firstSlideId
    }
  });
}

return [{
  json: {
    presentationId: presentationId,
    presentation_id: presentationId,
    presentation_url: 'https://docs.google.com/presentation/d/' + presentationId,
    titre: (slidesData.title || slidesData.titre || (prepNode && prepNode.titre) || 'Présentation'),
    theme: (slidesData.theme || (prepNode && prepNode.theme) || 'stark'),
    slides_count: slidesList.length,
    download_url: (prepNode && prepNode.download_url) || ('/downloads/' + presentationId + '.pptx'),
    filename: (prepNode && prepNode.filename) || 'presentation.pptx',
    requests: requests
  }
}];

const prepData = $node['Préparer Requêtes Batch Slides'].json;
const httpResult = $input.first().json;

const hasError = httpResult && (httpResult.error !== undefined || (httpResult.statusCode && httpResult.statusCode >= 400));

return [{
  json: {
    status: hasError ? 'error' : 'success',
    reply: hasError ? ('Erreur Google Slides: ' + JSON.stringify(httpResult.error || httpResult)) : ('La présentation Google Slides ' + prepData.titre + ' a été créée et mise en page avec succès (' + prepData.slides_count + ' diapositives).'),
    titre: prepData.titre,
    theme: prepData.theme,
    slides_count: prepData.slides_count,
    presentation_id: prepData.presentation_id,
    presentation_url: prepData.presentation_url,
    download_url: prepData.download_url,
    filename: prepData.filename,
    batch_applied: !hasError,
    batch_result: hasError ? (httpResult.error || httpResult) : { replies_count: (httpResult.replies || []).length },
    timestamp: new Date().toISOString()
  }
}];

const body = $input.first().json.body || $input.first().json || {};
const typeEntree = (body.type_entree || 'note').trim().toLowerCase();
const titre = (body.titre || 'Note rapide').trim();
const contenu = (body.contenu || '').trim();
const tags = Array.isArray(body.tags) ? body.tags : [];

return [{
  json: {
    type_entree: typeEntree,
    titre: titre,
    contenu: contenu,
    tags: tags,
    database_id: body.database_id || 'jarvis_default_notes_db',
    created_at: new Date().toISOString()
  }
}];

const prep = $node['Formater Entrée Notion'].json;
const notionRes = $input.first().json;

return [{
  json: {
    status: 'success',
    reply: 'L entrée ' + prep.titre + ' (' + prep.type_entree + ') a été enregistrée dans Notion.',
    titre: prep.titre,
    type_entree: prep.type_entree,
    notion_id: notionRes.id || ('notion_item_' + Date.now()),
    notion_url: notionRes.url || 'https://notion.so/jarvis-notes',
    tags: prep.tags,
    timestamp: new Date().toISOString()
  }
}];
